define("tiny_omeroembed/commands", ["exports", "editor_tiny/utils", "tiny_omeroembed/ui", "core/str", "tiny_omeroembed/common"], function(exports, Utils, Ui, Str, Common) {
    "use strict";
    Object.defineProperty(exports, "__esModule", {value: true});

    function getIconMarkup(identifier, iconcomponent) {
        return Utils.getImagePath(identifier, iconcomponent).then(function(url) {
            return fetch(url).then(function(response) {
                return response.text();
            });
        });
    }

    exports.getSetup = function() {
        return Promise.all([
            Str.getString("buttontitle", Common.component),
            getIconMarkup("icon", Common.component),
        ]).then(function(results) {
            var buttonText = results[0];
            var buttonMarkup = results[1];

            return function(editor) {
                if (editor.id === "id_introeditor" || editor.id.endsWith("_introeditor")) {
                    return;
                }

                editor.ui.registry.addIcon(Common.icon, buttonMarkup);

                editor.ui.registry.addButton(Common.buttonName, {
                    icon: Common.icon,
                    tooltip: buttonText,
                    onAction: function() {
                        Ui.handleAction(editor);
                    },
                });

                editor.ui.registry.addMenuItem(Common.buttonName, {
                    icon: Common.icon,
                    text: buttonText,
                    onAction: function() {
                        Ui.handleAction(editor);
                    },
                });
            };
        });
    };
});
